  str_n23_level_desc_1 = "-",
  str_n23_level_desc_2 = "คุณและ Vice ไปถึงบ้านผีสิง Andersen และพบว่าเจ้าของนั้นเป็นใบหน้าที่คุ้นเคย",
  str_n23_level_desc_3 = "ในทางเดินหนึ่ง คุณจะได้พบกับผู้กำกับหนังสยองขวัญจอนนี่และทีมงานของเขา ในไม่ช้าคุณจะพบตัวตนอื่นของ Minos...",
  str_n23_level_desc_4 = "ซาดีแยกตัวจากจอนนี่และตามคุณทัน โดยนำแผนผังตำแหน่งของลูกเรือไปพร้อมกับเธอ",
  str_n23_level_desc_5 = "บุคคลลึกลับสวมหน้ากากซึ่งเป็นผู้นำฝูง Eclipsites ไล่ตามคุณ เรื่องนี้มีบางอย่างที่แปลกมาก...",
  str_n23_level_desc_6 = "ห้องมืด หุ่นน่าขนลุก และเสียงน้ำหยด... มีคนตั้งใจออกแบบสิ่งนี้... ใช่ไหม?",
  str_n23_level_desc_7 = "ขณะที่หัวใจของคุณยังคงสั่นเทาจากความกลัว กรงเล็บเหล็กยื่นออกมาหาคุณ พยายามจะบอกอะไรบางอย่างกับคุณ...",
  str_n23_level_desc_8 = "-",
  str_n23_level_desc_9 = "คุณครุ่นคิดถึงทุกสิ่งที่เกิดขึ้นจนถึงตอนนี้ สรุปว่า... เดี๋ยวนะ มีใครอยู่ข้างนอกมั้ย?",
  str_n23_level_desc_10 = "คุณกำลังเข้าใกล้ความจริงมากขึ้นเรื่อยๆ! ส่งศัตรูเหล่านี้ก่อนที่จะขัดขวางการอนุมานของคุณ!",
  str_n23_level_desc_11 = "คุณและเพื่อน ๆ ของคุณโกรธจัดกับเหตุการณ์ที่เกิดขึ้นในคืนนี้ ต้องมีใครบางคนรับผิดชอบในทุกสิ่ง รวมถึงสุริยุปราคาที่อยู่ตรงหน้าคุณ",
  str_n23_level_desc_12 = "วิ่งหนี. และสิ่งที่คุณทำ...อย่าหันหลังกลับ",
  str_n23_level_desc_13 = "รีบ! นำ Eclipsites ที่เหลือที่ขวางทางคุณออกไป! เดี๋ยวนะ... ลิลิก้ากับซาดีอยู่ที่ไหน?",
  str_n23_level_desc_14 = "สิ่งที่คุณกลัว สิ่งที่คุณไม่กล้าเผชิญ อยู่ตรงหน้าคุณแล้ว ไม่มีทางเลือกอื่นนอกจากต้องต่อสู้ในตอนนี้",
  str_n23_level_desc_15 = "-",
  str_n23_level_desc_long_1 = "พาดหัวหนังสือพิมพ์ของ Umbraton ให้รายละเอียดเกี่ยวกับนักแสดงหญิงที่ไม่รู้จักที่หายตัวไประหว่างการถ่ายทำภาพยนตร์สยองขวัญและดึงดูดความสนใจของคุณอย่างไม่มีการแบ่งแยก ในขณะเดียวกัน Vice ได้จดจ่ออยู่กับการเปิดตัวครั้งใหญ่ของ Andersen Haunted House ซึ่งอ้างว่ามี \"ปรากฏการณ์เหนือธรรมชาติที่แท้จริง\" เธอเชิญคุณไปที่บ้านผีสิง แต่คุณไม่สามารถละความคิดของคุณออกจากการหายตัวไปได้",
  str_n23_level_desc_long_2 = "ตามที่คาดไว้ คฤหาสน์นี้เป็นของนีน่า แอนเดอร์เซ็น Minos ทำตามคำแนะนำของ Nina เพื่อแนะนำคุณและ Vice ผ่านสถานที่ ข้างในคุณจะพบกับ Lilica เพื่อนผู้หลงใหลในอาถรรพณ์ เธอทักทายคุณด้วยความกระตือรือร้นและดูเหมือนจะต้องการบันทึกการผจญภัยครั้งนี้และแปลงเป็นภาพยนตร์",
  str_n23_level_desc_long_3 = "คุณพบผู้กำกับในกรณีของนักแสดงที่หายตัวไป เขามีแผนสำหรับภาพยนตร์เรื่องใหม่อยู่แล้วและแนะนำให้คุณรู้จักกับนักแสดงหญิงสองคนคือโกลดี้และซาดี คุณเรียนรู้จากการสนทนาว่านีน่าและไมนอสไม่ตรงกันเพราะจอนนี่ต้องการถ่ายทำในระยะยาวในคฤหาสน์ Minos ติดอยู่ตรงกลางและทำหน้าที่เป็นโปรดิวเซอร์ชั่วคราวชั่วคราว",
  str_n23_level_desc_long_4 = "ตามแผนภูมิตำแหน่งของ Sadie และการเป็นผู้นำของ Minos คุณจะไปถึงห้องนอน สถานที่ถ่ายทำแห่งแรก คุณพบโทรทัศน์เครื่องเก่าที่มีภาพน่าขนลุกอยู่บนหน้าจอ การสนทนาสั้น ๆ กับเพื่อนที่สวมหน้ากากบ่งบอกว่าคุณไม่สามารถออกจากบ้านผีสิงทั้งเป็นได้",
  str_n23_level_desc_long_5 = "เมื่อทำแบบทดสอบนี้ คุณไม่มีทางเลือกอื่นนอกจากต้องต่อสู้กับเพื่อนที่สวมหน้ากากและ Eclipsites แต่เพื่อนที่สวมหน้ากากปิดการจู่โจม ปรากฎว่านีน่าอยู่ภายใต้หน้ากาก และสุริยุปราคาก็เป็นเพื่อนในชุดเครื่องแต่งกาย นีน่าภูมิใจในการแสดง \"สถานที่ท่องเที่ยว\" ของเธอ ลิลิกา คนรักอาถรรพณ์พาไวซ์ผู้ผิดหวังและคนอื่นๆ ไปยังสถานที่ถ่ายทำต่อไป",
  str_n23_level_desc_long_6 = "สถานที่ที่สองคือโชว์รูม อากาศชื้นและหุ่นที่น่าขนลุกเป็นเครื่องเตือนใจว่าบ้านนี้มีผีสิง เสียงเพลงและเสียงน้ำหยดเริ่มส่งเสียงก้องไปทั่วบริเวณ แต่เมื่อซาดีเยาะเย้ยที่ห้องนั่งเล่นราคาถูก น้ำที่หยดลงมาดูเหมือนจะพิสูจน์ว่าเธอคิดผิด",
  str_n23_level_desc_long_7 = "นอกโชว์รูม คุณเจอมีอา ที่มาที่นี่คนเดียว ดูเหมือนว่าเธอจะสนุกกับการท่องเที่ยวด้วยตัวเอง และก่อนที่จะจากกัน เธอส่งคำเตือนที่อาจเชื่อมโยงอย่างลับๆ กับตัวเธอเองอย่างลับๆ ว่า: ระวังและอย่าให้ \"เธอ\" จับคุณได้",
  str_n23_level_desc_long_8 = "คุณตาม Minos ไปยังตำแหน่งสุดท้าย—ชั้นใต้ดิน ซึ่งคุณสังเกตเห็นเบาะแสแปลกๆ ต่างๆ ที่บ่งบอกว่าเจ้าของคนก่อนได้ลงโทษเด็กเล็กๆ นอกจากนี้ยังมีบันทึกของทีมงานภาพยนตร์อยู่ใกล้ๆ กับเนื้อหาที่ทำให้ไม่สงบ ทันใดนั้น ห้องใต้ดินก็มืดลง และคุณได้เห็นสถานที่ที่น่ากลัวผ่านกล้องส่องทางไกลตอนกลางคืน... \nแต่มันกลับกลายเป็นว่าไม่มีอะไรเลย คุณเป็นคนหวาดระแวงโดยไม่มีเหตุผล",
  str_n23_level_desc_long_9 = "หลังจากตรวจดูสถานที่ถ่ายทำทั้งหมดแล้ว ไมนอสก็นำคุณกลับไปที่สำนักงานเพื่อหาเบาะแส คุณยอมรับว่าแรงจูงใจของทีมงานที่อยู่เบื้องหลังการหายตัวไปของนักแสดงคือกุญแจสำคัญ แต่วินาทีต่อมา Eclipsites ก็ปิดล้อมสำนักงาน...",
  str_n23_level_desc_long_10 = "เมื่อกำจัด Eclipsites แล้วคุณจะกลับไปที่สำนักงาน ไมนอสค้นหาไฟล์เพื่อหาเบาะแสเพิ่มเติม ลิลิกานำภาพที่พัฒนาแล้วกลับมาแสดงให้ทุกคนเห็น แต่กลับพบว่ามีแขนที่ไม่ได้เป็นของใครในห้องนั้น",
